// Generated from committed Zhanerke design assets.
export const MISHIPASS_LOGO_SRC = "/brand/logo.jpeg";
export const MISHIPASS_BACKGROUND_SRC = "/assets/background.jpeg";
export const MISHIPASS_PAW_SRC = "/brand/paw.png";

const PAW_BASE64 = "";

const LOGO_BASE64 = "";
const BACKGROUND_BASE64 = "";

function assetResponse(base64: string, contentType: string, request: Request): Response {
  const bytes = Uint8Array.from(atob(base64), c => c.charCodeAt(0));
  return new Response(request.method === "HEAD" ? null : bytes, {
    headers: {
      "Content-Type": contentType,
      "Cache-Control": "public, max-age=31536000, immutable",
      "X-Content-Type-Options": "nosniff",
    },
  });
}

export function handleBrandAsset(pathname: string, request: Request): Response | null {
  if (pathname === MISHIPASS_LOGO_SRC) return assetResponse(LOGO_BASE64, "image/jpeg", request);
  if (pathname === MISHIPASS_BACKGROUND_SRC) return assetResponse(BACKGROUND_BASE64, "image/jpeg", request);
  if (pathname === MISHIPASS_PAW_SRC) return assetResponse(PAW_BASE64, "image/png", request);
  return null;
}

